// Offline tuning for the hand-anchor One Euro filter (ONY-502).
//
// A capture is a provenance-stamped anchor trace: one position per tracking
// sample, on the host monotonic clock. `PoseCapture.fromRecording` derives a
// trace from an ONY-249 `PoseRecording`, so a hardware capture recorded in the
// app can be replayed without changing the recorder format. The synthetic
// fixtures under `test/fixtures/pose_filter_captures/synthetic` use the same
// shape and are generated by `tool/generate_pose_captures.dart`.
//
// The acceptance bars, motion classes and search grid are ONY-501's
// `filter-spec` revision 4. Where the run sheet and that document disagree,
// the document wins.
import 'dart:convert';
import 'dart:math' as math;

import 'package:vector_math/vector_math_64.dart';
import 'package:wmr_tracking/wmr_tracking.dart';

/// Motion class of a capture, named after `filter-spec` rev 4 section 8.
enum PoseMotion {
  /// Segment S: controller at rest, 10 s. Scores static jitter J.
  still,

  /// Segment D: held roughly still but drifting at 10-50 cm/s, 10 s.
  /// Scores J_D.
  heldDrift,

  /// Slow pan at 10 cm/s. Scores lag against the 160 ms regression bound.
  slowPan,

  /// Medium pan at 50 cm/s. Scores lag against the 20 ms bound.
  mediumPan,

  /// Fast flick at 150 cm/s. Scores lag against the 20 ms bound.
  fastFlick,

  /// Hand-anchor motion with a tracking dropout (an occlusion). Diagnostic
  /// only; rev 4 has no bar for this class.
  occlusion,
}

/// One anchor sample: the position the fuser would feed the filter, and the
/// anchor sample's own host timestamp.
class PoseCaptureSample {
  const PoseCaptureSample({required this.timeNs, required this.position});

  final int timeNs;
  final Vector3 position;

  List<Object?> toJson() => [
    timeNs,
    _round(position.x, 7),
    _round(position.y, 7),
    _round(position.z, 7),
  ];

  factory PoseCaptureSample.fromJson(Object? json) {
    if (json is! List || json.length != 4) {
      throw const FormatException('capture sample must be [ns, x, y, z]');
    }
    final time = json[0];
    if (time is! int || time < 0) {
      throw const FormatException('capture sample timestamp must be an int');
    }
    final values = <double>[];
    for (final element in json.skip(1)) {
      if (element is! num || !element.isFinite) {
        throw const FormatException('capture sample must contain numbers');
      }
      values.add(element.toDouble());
    }
    return PoseCaptureSample(
      timeNs: time,
      position: Vector3(values[0], values[1], values[2]),
    );
  }
}

/// A provenance-stamped sequence of raw anchor samples.
class PoseCapture {
  PoseCapture({
    required this.runtime,
    required this.motion,
    required this.run,
    required this.provenance,
    required List<PoseCaptureSample> samples,
  }) : samples = List.unmodifiable(samples);

  static const String format = 'wmr-pose-capture';
  static const int currentVersion = 1;

  final TrackingVendor runtime;
  final PoseMotion motion;

  /// Run index within a `(runtime, motion)` cell, starting at 1.
  final int run;

  /// Where the trace came from. Synthetic traces say so; a hardware trace
  /// carries the app commit and firmware SHA.
  final Map<String, Object?> provenance;

  final List<PoseCaptureSample> samples;

  String? get appCommit => provenance['app_commit'] as String?;
  String? get firmwareSha => provenance['firmware_sha'] as String?;
  bool get synthetic => provenance['kind'] == 'synthetic';

  Map<String, Object?> toJson() => {
    'format': format,
    'version': currentVersion,
    'runtime': runtime.name,
    'motion': motion.name,
    'run': run,
    'provenance': provenance,
    'samples': [for (final sample in samples) sample.toJson()],
  };

  /// Compact deterministic JSON; the traces are machine-read fixtures.
  String encode() => jsonEncode(toJson());

  factory PoseCapture.decode(String source) {
    Object? json;
    try {
      json = jsonDecode(source);
    } on FormatException catch (error) {
      throw PoseCaptureException('not valid JSON: ${error.message}', error);
    }
    return PoseCapture.fromJson(json);
  }

  factory PoseCapture.fromJson(Object? json) {
    if (json is! Map) {
      throw const PoseCaptureException('capture must be an object');
    }
    if (json['format'] != format || json['version'] != currentVersion) {
      throw const PoseCaptureException('unsupported capture document');
    }
    final runtime = _vendor(json['runtime']);
    final motion = _motion(json['motion']);
    final run = json['run'];
    if (run is! int || run < 1) {
      throw const PoseCaptureException('run must be a positive integer');
    }
    final provenance = json['provenance'];
    if (provenance is! Map) {
      throw const PoseCaptureException('provenance must be an object');
    }
    final rawSamples = json['samples'];
    if (rawSamples is! List || rawSamples.length < 2) {
      throw const PoseCaptureException('samples must be a non-empty list');
    }
    final samples = <PoseCaptureSample>[];
    for (final raw in rawSamples) {
      final sample = PoseCaptureSample.fromJson(raw);
      if (samples.isNotEmpty && sample.timeNs <= samples.last.timeNs) {
        throw const PoseCaptureException(
          'capture sample timestamps must increase',
        );
      }
      samples.add(sample);
    }
    return PoseCapture(
      runtime: runtime,
      motion: motion,
      run: run,
      provenance: Map<String, Object?>.unmodifiable(provenance),
      samples: samples,
    );
  }

  /// Derives an anchor trace from an ONY-249 recording.
  ///
  /// Repeated copies of the same tracking frame are collapsed: the recorder
  /// samples the viewer, and the filter must see one input per anchor sample.
  /// The trace is the **raw anchor joint position**, not the controller
  /// position: `filter-spec` section 3 filters the joint and applies
  /// `R_imu * offset` afterwards, so the harness measures the quantity the
  /// filter actually sees and does not need a grip offset.
  factory PoseCapture.fromRecording(
    PoseRecording recording, {
    required TrackingVendor runtime,
    required PoseMotion motion,
    int run = 1,
    TrackedHand hand = TrackedHand.right,
    Map<String, Object?> provenance = const {},
  }) {
    final samples = <PoseCaptureSample>[];
    int? lastFrameTime;
    for (final sample in recording.samples) {
      final frame = sample.tracking;
      if (frame == null) continue;
      final anchor = frame.hand(hand)?.controllerAnchor;
      if (anchor == null || !anchor.isTracked) continue;
      final time = frame.fusionTimeNs;
      if (lastFrameTime == time) continue;
      lastFrameTime = time;
      final position = anchor.pose.translation;
      if (!_finite(position)) continue;
      samples.add(
        PoseCaptureSample(timeNs: time, position: Vector3.copy(position)),
      );
    }
    if (samples.length < 2) {
      throw const PoseCaptureException(
        'recording contains fewer than two hand-anchor samples',
      );
    }
    return PoseCapture(
      runtime: runtime,
      motion: motion,
      run: run,
      provenance: Map<String, Object?>.unmodifiable(provenance),
      samples: samples,
    );
  }

  static TrackingVendor _vendor(Object? value) {
    for (final vendor in TrackingVendor.values) {
      if (vendor.name == value) return vendor;
    }
    throw PoseCaptureException('unknown runtime: $value');
  }

  static PoseMotion _motion(Object? value) {
    for (final motion in PoseMotion.values) {
      if (motion.name == value) return motion;
    }
    throw PoseCaptureException('unknown motion: $value');
  }
}

/// A malformed or unsupported capture.
class PoseCaptureException implements Exception {
  const PoseCaptureException(this.message, [this.cause]);

  final String message;
  final Object? cause;

  @override
  String toString() => 'PoseCaptureException: $message';
}

/// Metrics for one replay of one capture.
class PoseFilterMetrics {
  const PoseFilterMetrics({
    this.jitterMm = 0,
    this.jitterDriftMm = 0,
    this.lagMedianMs = 0,
    this.lagPeakMs = 0,
    this.step90Ms = 0,
    this.addedDelayMs = 0,
    this.samples = 0,
  });

  /// J: RMS distance of the filtered position from its 1 s moving mean.
  final double jitterMm;

  /// J_D: RMS of the filtered position's residual from a local quadratic
  /// (Savitzky-Golay, 1 s window, order 2) fit.
  final double jitterDriftMm;

  /// Best-fit time shift between raw and filtered over the whole capture.
  final double lagMedianMs;

  /// Worst best-fit shift over 1 s windows.
  final double lagPeakMs;

  /// Filtered 90 % rise time measured from the raw 10 % crossing.
  final double step90Ms;

  /// Filtered 90 % crossing minus the raw 90 % crossing.
  final double addedDelayMs;

  final int samples;

  Map<String, Object?> toJson() => {
    'jitter_mm': _round(jitterMm),
    'jitter_drift_mm': _round(jitterDriftMm),
    'lag_median_ms': _round(lagMedianMs),
    'lag_peak_ms': _round(lagPeakMs),
    'step90_ms': _round(step90Ms),
    'added_delay_ms': _round(addedDelayMs),
    'samples': samples,
  };
}

/// One point in the constant grid.
class TuningPoint {
  const TuningPoint({
    required this.minCutoffHz,
    required this.beta,
    required this.dCutoffHz,
  });

  final double minCutoffHz;

  /// Hertz per centimetre per second, matching [OneEuroFilter.beta]. The
  /// filter converts metre-scale samples to centimetres internally.
  final double beta;
  final double dCutoffHz;

  PoseFilterConfig config(Duration minDt) => PoseFilterConfig(
    minCutoffHz: minCutoffHz,
    beta: beta,
    dCutoffHz: dCutoffHz,
    minDt: minDt,
  );

  Map<String, Object?> toJson() => {
    'min_cutoff_hz': minCutoffHz,
    'beta': beta,
    'd_cutoff_hz': dCutoffHz,
  };

  @override
  String toString() => 'minCutoff=$minCutoffHz beta=$beta dCutoff=$dCutoffHz';
}

/// One axis of the search grid.
class PoseAxis {
  const PoseAxis({required this.min, required this.max, required this.step});

  final double min;
  final double max;
  final double step;

  int get count => ((max - min) / step).round() + 1;

  List<double> get values => [
    for (var i = 0; i < count; i++) _round(min + i * step, 6),
  ];

  /// 50 % more points at the same step, extending the low end. Refuses to
  /// cross zero, which is not a valid cutoff or speed coefficient.
  PoseAxis? extendStart() {
    final extra = math.max(1, ((count - 1) * 0.5).round());
    final candidate = _round(min - extra * step, 6);
    final floor = step;
    final extended = candidate < floor ? floor : candidate;
    if (extended >= min - 1e-9) return null;
    return PoseAxis(min: extended, max: max, step: step);
  }

  /// 50 % more points at the same step, extending the high end.
  PoseAxis? extendEnd() {
    final extra = math.max(1, ((count - 1) * 0.5).round());
    return PoseAxis(min: min, max: _round(max + extra * step, 6), step: step);
  }

  bool atMin(double value) => (value - min).abs() < 1e-6;

  bool atMax(double value) => (value - max).abs() < 1e-6;

  Map<String, Object?> toJson() => {
    'min': min,
    'max': max,
    'step': step,
    'points': count,
  };
}

/// The full search grid. `filter-spec` section 7 is normative: 13 minCutoff
/// values x 41 beta values x 8 dCutoff values = 4,264 points per runtime.
class PoseGrid {
  const PoseGrid({
    required this.minCutoff,
    required this.beta,
    required this.dCutoff,
  });

  final PoseAxis minCutoff;
  final PoseAxis beta;
  final PoseAxis dCutoff;

  static const PoseGrid standard = PoseGrid(
    minCutoff: PoseAxis(min: 1.0, max: 4.0, step: 0.25),
    beta: PoseAxis(min: 0.00, max: 0.40, step: 0.01),
    dCutoff: PoseAxis(min: 0.5, max: 4.0, step: 0.5),
  );

  int get pointCount => minCutoff.count * beta.count * dCutoff.count;

  Iterable<TuningPoint> get points sync* {
    for (final minCutoffHz in minCutoff.values) {
      for (final betaValue in beta.values) {
        for (final dCutoffHz in dCutoff.values) {
          yield TuningPoint(
            minCutoffHz: minCutoffHz,
            beta: betaValue,
            dCutoffHz: dCutoffHz,
          );
        }
      }
    }
  }

  /// Axes where [point] sits on a boundary that limits a bar. `filter-spec`
  /// rev 4 section 7 calls such a winner inconclusive.
  List<String> edgesAt(TuningPoint point) {
    final edges = <String>[];
    if (minCutoff.atMin(point.minCutoffHz) ||
        minCutoff.atMax(point.minCutoffHz)) {
      edges.add('minCutoff');
    }
    if (beta.atMax(point.beta)) edges.add('beta');
    if (dCutoff.atMin(point.dCutoffHz) || dCutoff.atMax(point.dCutoffHz)) {
      edges.add('dCutoff');
    }
    return edges;
  }

  /// Extends every bar-limiting axis [point] touches by 50 % at the same step.
  /// Returns null when nothing can be extended.
  PoseGrid? extendedFor(TuningPoint point) {
    var nextMinCutoff = minCutoff;
    var nextBeta = beta;
    var nextDCutoff = dCutoff;
    var changed = false;

    if (minCutoff.atMin(point.minCutoffHz)) {
      final extended = minCutoff.extendStart() ?? minCutoff.extendEnd();
      if (extended != null) {
        nextMinCutoff = extended;
        changed = true;
      }
    } else if (minCutoff.atMax(point.minCutoffHz)) {
      final extended = minCutoff.extendEnd();
      if (extended != null) {
        nextMinCutoff = extended;
        changed = true;
      }
    }

    if (beta.atMax(point.beta)) {
      final extended = beta.extendEnd();
      if (extended != null) {
        nextBeta = extended;
        changed = true;
      }
    }

    if (dCutoff.atMin(point.dCutoffHz)) {
      // A 0.5 Hz floor cannot grow downward at a 0.5 Hz step, so grow the
      // other end rather than reporting an extension that does not exist.
      final extended = dCutoff.extendStart() ?? dCutoff.extendEnd();
      if (extended != null) {
        nextDCutoff = extended;
        changed = true;
      }
    } else if (dCutoff.atMax(point.dCutoffHz)) {
      final extended = dCutoff.extendEnd();
      if (extended != null) {
        nextDCutoff = extended;
        changed = true;
      }
    }

    if (!changed) return null;
    return PoseGrid(
      minCutoff: nextMinCutoff,
      beta: nextBeta,
      dCutoff: nextDCutoff,
    );
  }

  Map<String, Object?> toJson() => {
    'min_cutoff_hz': minCutoff.toJson(),
    'beta': beta.toJson(),
    'd_cutoff_hz': dCutoff.toJson(),
    'points': pointCount,
  };
}

/// One evaluated grid row for a runtime.
class TuningRow {
  const TuningRow({
    required this.point,
    required this.jitterMm,
    required this.jitterDriftMm,
    required this.lagSlowMedianMs,
    required this.lagMedianMs,
    required this.step90Ms,
  });

  final TuningPoint point;
  final double jitterMm;
  final double jitterDriftMm;
  final double lagSlowMedianMs;
  final double lagMedianMs;
  final double step90Ms;

  bool get passes =>
      jitterMm <= poseFilterJitterLimitMm &&
      jitterDriftMm <= poseFilterDriftJitterLimitMm &&
      lagMedianMs <= poseFilterLagLimitMs &&
      lagSlowMedianMs <= poseFilterSlowLagLimitMs;

  Map<String, Object?> toJson() => {
    ...point.toJson(),
    'jitter_mm': _round(jitterMm),
    'jitter_drift_mm': _round(jitterDriftMm),
    'lag_slow_median_ms': _round(lagSlowMedianMs),
    'lag_median_ms': _round(lagMedianMs),
    'step90_ms': _round(step90Ms),
    'passes': passes,
  };
}

/// The ONY-501 acceptance bounds (`filter-spec` rev 4 section 1).
const double poseFilterJitterLimitMm = 0.5;
const double poseFilterDriftJitterLimitMm = 0.75;
const double poseFilterLagLimitMs = 20.0;
const double poseFilterSlowLagLimitMs = 160.0;

/// A rerun after a winner touched a grid boundary.
class TuningExtension {
  const TuningExtension({
    required this.grid,
    required this.rows,
    required this.chosen,
    required this.inconclusive,
  });

  final PoseGrid grid;
  final List<TuningRow> rows;
  final TuningRow? chosen;
  final bool inconclusive;

  Map<String, Object?> toJson() => {
    'grid': grid.toJson(),
    'chosen': chosen?.toJson(),
    'inconclusive': inconclusive,
    'rows': [for (final row in rows) row.toJson()],
  };
}

/// Per-runtime result of the grid search.
class TuningReport {
  const TuningReport({
    required this.runtime,
    required this.grid,
    required this.rows,
    required this.chosen,
    required this.rawJitterMm,
    required this.bypass,
    required this.captureCount,
    required this.missingMotions,
    required this.inconclusive,
    this.extension,
  });

  final TrackingVendor runtime;
  final PoseGrid grid;
  final List<TuningRow> rows;
  final TuningRow? chosen;
  final double rawJitterMm;
  final bool bypass;
  final int captureCount;
  final List<String> missingMotions;
  final bool inconclusive;
  final TuningExtension? extension;

  bool get passed =>
      !inconclusive && missingMotions.isEmpty && (bypass || chosen != null);

  Map<String, Object?> toJson() => {
    'runtime': runtime.name,
    'captures': captureCount,
    'raw_jitter_mm': _round(rawJitterMm),
    'bypass': bypass,
    'missing_motions': missingMotions,
    'passed': passed,
    'inconclusive': inconclusive,
    'grid': grid.toJson(),
    'chosen': chosen?.toJson(),
    'rows': [for (final row in rows) row.toJson()],
    'extension': extension?.toJson(),
  };
}

/// Replays [capture] through [config] and measures the rev 4 metrics.
///
/// Only new anchor samples are filtered, matching the fuser after ONY-502.
PoseFilterMetrics analyzeCapture(
  PoseCapture capture,
  PoseFilterConfig config, {
  bool includePeak = false,
}) {
  final filter = config.createFilter();
  final filtered = <Vector3>[];
  final times = <int>[];
  for (final sample in capture.samples) {
    filtered.add(filter.filter(sample.position, sample.timeNs));
    times.add(sample.timeNs);
  }
  final raw = [for (final sample in capture.samples) sample.position];
  final originNs = capture.samples.first.timeNs;

  switch (capture.motion) {
    case PoseMotion.still:
      return PoseFilterMetrics(
        jitterMm: _jitterMm(times, filtered, originNs: originNs),
        samples: filtered.length,
      );
    case PoseMotion.heldDrift:
      return PoseFilterMetrics(
        jitterDriftMm: _jitterDriftMm(times, filtered, originNs: originNs),
        samples: filtered.length,
      );
    case PoseMotion.slowPan:
    case PoseMotion.mediumPan:
    case PoseMotion.fastFlick:
    case PoseMotion.occlusion:
      final lag = _bestShiftMs(
        times,
        raw,
        filtered,
        fromIndex: _warmup(times, originNs),
      );
      final peak = includePeak ? _peakShiftMs(times, raw, filtered) : 0.0;
      final step = capture.motion == PoseMotion.fastFlick
          ? _stepResponse(times, raw, filtered)
          : const _StepResponse.zero();
      return PoseFilterMetrics(
        lagMedianMs: lag,
        lagPeakMs: peak,
        step90Ms: step.t90Ms,
        addedDelayMs: step.addedDelayMs,
        samples: filtered.length,
      );
  }
}

/// Runs the full `filter-spec` rev 4 grid over a capture set, grouped by
/// runtime. A winner on a bar-limiting boundary triggers one full rerun with
/// that axis extended 50 % and is not reported as a pass.
List<TuningReport> tunePoseFilter(
  List<PoseCapture> captures, {
  Duration minDt = OneEuroFilter.defaultMinDt,
  PoseGrid grid = PoseGrid.standard,
}) {
  final byRuntime = <TrackingVendor, List<PoseCapture>>{};
  for (final capture in captures) {
    byRuntime.putIfAbsent(capture.runtime, () => []).add(capture);
  }
  final reports = <TuningReport>[];
  for (final entry in byRuntime.entries) {
    final runtimeCaptures = entry.value;
    final still = _motionCaptures(runtimeCaptures, PoseMotion.still);
    final drift = _motionCaptures(runtimeCaptures, PoseMotion.heldDrift);
    final slow = _motionCaptures(runtimeCaptures, PoseMotion.slowPan);
    final medium = _motionCaptures(runtimeCaptures, PoseMotion.mediumPan);
    final fast = _motionCaptures(runtimeCaptures, PoseMotion.fastFlick);
    final moving = [...medium, ...fast];
    final missing = <String>[
      if (still.isEmpty) PoseMotion.still.name,
      if (drift.isEmpty) PoseMotion.heldDrift.name,
      if (slow.isEmpty) PoseMotion.slowPan.name,
      if (medium.isEmpty) PoseMotion.mediumPan.name,
      if (fast.isEmpty) PoseMotion.fastFlick.name,
    ];
    final rawJitter = still.isEmpty
        ? double.nan
        : _worst([for (final capture in still) _rawJitterMm(capture)]);
    final bypass = rawJitter.isFinite && rawJitter <= poseFilterJitterLimitMm;

    final base = _evaluateGrid(
      grid: grid,
      still: still,
      drift: drift,
      slow: slow,
      moving: moving,
      minDt: minDt,
    );
    var chosen = base.chosen;
    TuningExtension? extension;
    var inconclusive = false;

    if (!bypass && chosen != null) {
      final edges = grid.edgesAt(chosen.point);
      if (edges.isNotEmpty) {
        final extended = grid.extendedFor(chosen.point);
        if (extended == null) {
          inconclusive = true;
        } else {
          final rerun = _evaluateGrid(
            grid: extended,
            still: still,
            drift: drift,
            slow: slow,
            moving: moving,
            minDt: minDt,
          );
          chosen = rerun.chosen;
          inconclusive =
              chosen == null || extended.edgesAt(chosen.point).isNotEmpty;
          extension = TuningExtension(
            grid: extended,
            rows: rerun.rows,
            chosen: chosen,
            inconclusive: inconclusive,
          );
        }
      }
    }

    reports.add(
      TuningReport(
        runtime: entry.key,
        grid: grid,
        rows: base.rows,
        chosen: chosen,
        rawJitterMm: rawJitter,
        bypass: bypass,
        captureCount: runtimeCaptures.length,
        missingMotions: missing,
        inconclusive: inconclusive,
        extension: extension,
      ),
    );
  }
  reports.sort((a, b) => a.runtime.name.compareTo(b.runtime.name));
  return reports;
}

class _Evaluation {
  const _Evaluation({required this.rows, required this.chosen});

  final List<TuningRow> rows;
  final TuningRow? chosen;
}

_Evaluation _evaluateGrid({
  required PoseGrid grid,
  required List<PoseCapture> still,
  required List<PoseCapture> drift,
  required List<PoseCapture> slow,
  required List<PoseCapture> moving,
  required Duration minDt,
}) {
  final rows = <TuningRow>[];
  // Every point is replayed. There is no early stop and no coarse-to-fine
  // pruning: `filter-spec` section 7 requires the whole grid.
  for (final point in grid.points) {
    final config = point.config(minDt);
    final stillMetrics = _metricsFor(still, config);
    final driftMetrics = _metricsFor(drift, config);
    final slowMetrics = _metricsFor(slow, config);
    final movingMetrics = _metricsFor(moving, config);
    rows.add(
      TuningRow(
        point: point,
        jitterMm: stillMetrics.jitterMm,
        jitterDriftMm: driftMetrics.jitterDriftMm,
        lagSlowMedianMs: slowMetrics.lagMedianMs,
        lagMedianMs: movingMetrics.lagMedianMs,
        step90Ms: movingMetrics.step90Ms,
      ),
    );
  }
  final passing = rows.where((row) => row.passes).toList()..sort(_compareRows);
  return _Evaluation(
    rows: rows,
    chosen: passing.isEmpty ? null : passing.first,
  );
}

int _compareRows(TuningRow a, TuningRow b) {
  final drift = a.jitterDriftMm.compareTo(b.jitterDriftMm);
  if (drift != 0) return drift;
  final lag = a.lagMedianMs.compareTo(b.lagMedianMs);
  if (lag != 0) return lag;
  final cutoff = a.point.minCutoffHz.compareTo(b.point.minCutoffHz);
  if (cutoff != 0) return cutoff;
  final beta = a.point.beta.compareTo(b.point.beta);
  if (beta != 0) return beta;
  return a.point.dCutoffHz.compareTo(b.point.dCutoffHz);
}

List<PoseCapture> _motionCaptures(
  List<PoseCapture> captures,
  PoseMotion motion,
) => [
  for (final capture in captures)
    if (capture.motion == motion) capture,
];

/// Best-fit time shift in milliseconds between [filtered] and [raw], capped to
/// the acceptance window.
double _bestShiftMs(
  List<int> times,
  List<Vector3> raw,
  List<Vector3> filtered, {
  int fromIndex = 0,
}) => _bestShiftRange(
  times,
  raw,
  filtered,
  fromIndex: fromIndex,
  toIndex: times.length - 1,
);

double _bestShiftRange(
  List<int> times,
  List<Vector3> raw,
  List<Vector3> filtered, {
  required int fromIndex,
  required int toIndex,
}) {
  // Coarse scan at 4 ms, then refine around the minimum at 1 ms. This is a
  // time-shift estimator, not grid pruning: every constant point is still
  // replayed.
  final coarse = _scanShift(
    times,
    raw,
    filtered,
    fromIndex: fromIndex,
    toIndex: toIndex,
    startMs: 0,
    endMs: 200,
    stepMs: 4,
  );
  final fine = _scanShift(
    times,
    raw,
    filtered,
    fromIndex: fromIndex,
    toIndex: toIndex,
    startMs: math.max(0, coarse - 4),
    endMs: math.min(200, coarse + 4),
    stepMs: 1,
  );
  return fine.toDouble();
}

int _scanShift(
  List<int> times,
  List<Vector3> raw,
  List<Vector3> filtered, {
  required int fromIndex,
  required int toIndex,
  required int startMs,
  required int endMs,
  required int stepMs,
}) {
  var best = startMs;
  var bestError = double.infinity;
  for (var shiftMs = startMs; shiftMs <= endMs; shiftMs += stepMs) {
    final shiftNs = shiftMs * 1000000;
    var sum = 0.0;
    var used = 0;
    var j = 0;
    for (var i = fromIndex; i <= toIndex; i++) {
      final target = times[i] - shiftNs;
      if (target < times[fromIndex]) continue;
      while (j + 1 <= toIndex && times[j + 1] <= target) {
        j++;
      }
      final double x;
      final double y;
      final double z;
      if (j + 1 > toIndex) {
        x = raw[j].x;
        y = raw[j].y;
        z = raw[j].z;
      } else {
        final span = times[j + 1] - times[j];
        final ratio = span <= 0 ? 0.0 : (target - times[j]) / span;
        x = raw[j].x + (raw[j + 1].x - raw[j].x) * ratio;
        y = raw[j].y + (raw[j + 1].y - raw[j].y) * ratio;
        z = raw[j].z + (raw[j + 1].z - raw[j].z) * ratio;
      }
      final dx = filtered[i].x - x;
      final dy = filtered[i].y - y;
      final dz = filtered[i].z - z;
      sum += dx * dx + dy * dy + dz * dz;
      used++;
    }
    if (used == 0) continue;
    final error = math.sqrt(sum / used);
    if (error < bestError) {
      bestError = error;
      best = shiftMs;
    }
  }
  return best;
}

double _peakShiftMs(
  List<int> times,
  List<Vector3> raw,
  List<Vector3> filtered,
) {
  if (times.length < 8) return 0;
  final span = times.last - times.first;
  final window = math.max(1000000000, span ~/ 4);
  var peak = 0.0;
  for (
    var start = times.first;
    start + window <= times.last;
    start += window ~/ 2
  ) {
    final end = start + window;
    var first = -1;
    var last = -1;
    for (var i = 0; i < times.length; i++) {
      if (times[i] >= start && times[i] <= end) {
        if (first < 0) first = i;
        last = i;
      }
    }
    if (first < 0 || last - first + 1 < 8) continue;
    final shift = _bestShiftRange(
      times,
      raw,
      filtered,
      fromIndex: first,
      toIndex: last,
    );
    if (shift > peak) peak = shift;
  }
  return peak;
}

class _StepResponse {
  const _StepResponse({required this.t90Ms, required this.addedDelayMs});

  const _StepResponse.zero() : t90Ms = 0, addedDelayMs = 0;

  final double t90Ms;
  final double addedDelayMs;
}

/// Measures the largest lateral step in the trace and the filtered 90 %
/// crossing. Values are milliseconds relative to the raw 10 % crossing.
_StepResponse _stepResponse(
  List<int> times,
  List<Vector3> raw,
  List<Vector3> filtered,
) {
  if (times.length < 8) return const _StepResponse.zero();
  var stepIndex = 0;
  var stepDistance = 0.0;
  for (var i = 0; i + 5 < times.length; i++) {
    final distance = (raw[i + 5] - raw[i]).length;
    if (distance > stepDistance) {
      stepDistance = distance;
      stepIndex = i;
    }
  }
  if (stepDistance < 0.001) return const _StepResponse.zero();
  // One step and its hold: long enough for a 25 Hz trace to settle, short
  // enough not to include the next flick two seconds later.
  final start = math.max(0, stepIndex - 20);
  final end = math.min(times.length - 1, stepIndex + 60);
  final from = raw[start];
  final to = raw[end];
  final displacement = to - from;
  final axis = displacement.length == 0
      ? Vector3(1, 0, 0)
      : displacement.normalized();
  double project(Vector3 value) => (value - from).dot(axis);
  final total = displacement.length;
  if (total < 0.001) return const _StepResponse.zero();

  double crossing(List<Vector3> values, double fraction) {
    final target = total * fraction;
    for (var i = start + 1; i <= end; i++) {
      final previous = project(values[i - 1]);
      final current = project(values[i]);
      if (previous < target && current >= target) {
        final ratio = (target - previous) / (current - previous);
        final ns = times[i - 1] + ((times[i] - times[i - 1]) * ratio).round();
        return (ns - times[start]) / 1000000.0;
      }
    }
    return (times[end] - times[start]) / 1000000.0;
  }

  final rawTen = crossing(raw, 0.10);
  final rawNinety = crossing(raw, 0.90);
  final filteredNinety = crossing(filtered, 0.90);
  return _StepResponse(
    t90Ms: filteredNinety - rawTen,
    addedDelayMs: filteredNinety - rawNinety,
  );
}

/// RMS distance of [values] from a 1 s moving mean, after a 1 s warmup.
double _jitterMm(
  List<int> times,
  List<Vector3> values, {
  required int originNs,
}) {
  final start = originNs + 1000000000;
  var sum = Vector3.zero();
  var left = 0;
  var used = 0;
  var residual = 0.0;
  for (var i = 0; i < times.length; i++) {
    sum += values[i];
    while (times[left] < times[i] - 1000000000) {
      sum -= values[left];
      left++;
    }
    if (times[i] < start) continue;
    final mean = sum / (i - left + 1).toDouble();
    residual += (values[i] - mean).length2;
    used++;
  }
  if (used == 0) return 0;
  return math.sqrt(residual / used) * 1000;
}

/// J_D: RMS of the residual from a local quadratic fit, 1 s window, order 2.
///
/// The window is centred on each sample and fitted by least squares, which is
/// the Savitzky-Golay quadratic filter for non-uniform timestamps. The value at
/// the centre is the constant term of the fit, so no kernel table is needed.
double _jitterDriftMm(
  List<int> times,
  List<Vector3> values, {
  required int originNs,
}) {
  final start = originNs + 1000000000;
  final halfWindowNs = 500000000;
  var left = 0;
  var right = 0;
  var used = 0;
  var residual = 0.0;
  for (var i = 0; i < times.length; i++) {
    if (times[i] < start) continue;
    final low = times[i] - halfWindowNs;
    final high = times[i] + halfWindowNs;
    while (left < i && times[left] < low) {
      left++;
    }
    if (right < i) right = i;
    while (right + 1 < times.length && times[right + 1] <= high) {
      right++;
    }
    if (right - left + 1 < 5) continue;

    var n = 0.0;
    var su = 0.0;
    var su2 = 0.0;
    var su3 = 0.0;
    var su4 = 0.0;
    var sx = 0.0;
    var sux = 0.0;
    var su2x = 0.0;
    var sy = 0.0;
    var suy = 0.0;
    var su2y = 0.0;
    var sz = 0.0;
    var suz = 0.0;
    var su2z = 0.0;
    for (var k = left; k <= right; k++) {
      final u = (times[k] - times[i]) / 1000000000.0;
      final u2 = u * u;
      final u3 = u2 * u;
      final u4 = u3 * u;
      final value = values[k];
      n += 1;
      su += u;
      su2 += u2;
      su3 += u3;
      su4 += u4;
      sx += value.x;
      sux += u * value.x;
      su2x += u2 * value.x;
      sy += value.y;
      suy += u * value.y;
      su2y += u2 * value.y;
      sz += value.z;
      suz += u * value.z;
      su2z += u2 * value.z;
    }

    final interceptX = _quadraticIntercept(n, su, su2, su3, su4, sx, sux, su2x);
    final interceptY = _quadraticIntercept(n, su, su2, su3, su4, sy, suy, su2y);
    final interceptZ = _quadraticIntercept(n, su, su2, su3, su4, sz, suz, su2z);
    if (interceptX == null || interceptY == null || interceptZ == null) {
      continue;
    }
    final dx = values[i].x - interceptX;
    final dy = values[i].y - interceptY;
    final dz = values[i].z - interceptZ;
    residual += dx * dx + dy * dy + dz * dz;
    used++;
  }
  if (used == 0) return 0;
  return math.sqrt(residual / used) * 1000;
}

/// Constant term of the least-squares quadratic `a + b*u + c*u^2`.
double? _quadraticIntercept(
  double n,
  double su,
  double su2,
  double su3,
  double su4,
  double sy,
  double suy,
  double su2y,
) {
  final determinant =
      n * (su2 * su4 - su3 * su3) -
      su * (su * su4 - su3 * su2) +
      su2 * (su * su3 - su2 * su2);
  if (determinant.abs() < 1e-12) return null;
  final numerator =
      sy * (su2 * su4 - su3 * su3) -
      su * (suy * su4 - su3 * su2y) +
      su2 * (suy * su3 - su2y * su2);
  return numerator / determinant;
}

int _warmup(List<int> times, int originNs) {
  final start = originNs + 1000000000;
  for (var i = 0; i < times.length; i++) {
    if (times[i] >= start) return i;
  }
  return 0;
}

PoseFilterMetrics _metricsFor(
  List<PoseCapture> captures,
  PoseFilterConfig config,
) {
  if (captures.isEmpty) return const PoseFilterMetrics();
  final metrics = [
    for (final capture in captures) analyzeCapture(capture, config),
  ];
  final lags = [for (final metric in metrics) metric.lagMedianMs]..sort();
  final peaks = [for (final metric in metrics) metric.lagPeakMs]..sort();
  final steps = [
    for (final metric in metrics)
      if (metric.step90Ms > 0) metric.step90Ms,
  ]..sort();
  final delays = [
    for (final metric in metrics)
      if (metric.step90Ms > 0) metric.addedDelayMs,
  ]..sort();
  return PoseFilterMetrics(
    jitterMm: _worst([for (final metric in metrics) metric.jitterMm]),
    jitterDriftMm: _worst([for (final metric in metrics) metric.jitterDriftMm]),
    lagMedianMs: _median(lags),
    lagPeakMs: peaks.isEmpty ? 0 : peaks.last,
    step90Ms: _median(steps),
    addedDelayMs: _median(delays),
    samples: metrics.fold<int>(0, (sum, metric) => sum + metric.samples),
  );
}

double _rawJitterMm(PoseCapture capture) {
  final times = [for (final sample in capture.samples) sample.timeNs];
  final raw = [for (final sample in capture.samples) sample.position];
  return _jitterMm(times, raw, originNs: capture.samples.first.timeNs);
}

double _median(List<double> values) {
  if (values.isEmpty) return 0;
  final middle = values.length ~/ 2;
  if (values.length.isOdd) return values[middle];
  return (values[middle - 1] + values[middle]) / 2;
}

double _worst(List<double> values) =>
    values.isEmpty ? 0 : values.reduce(math.max);

bool _finite(Vector3 value) =>
    value.x.isFinite && value.y.isFinite && value.z.isFinite;

double _round(double value, [int digits = 3]) =>
    value.isFinite ? double.parse(value.toStringAsFixed(digits)) : value;
